"use client"

/** @noSkeleton renders an invisible scroll marker, not a value — there is nothing behind it to wait for. */

import React from "react"
import { cn } from "@heroui/react"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"

/** Props for {@link InfiniteScrollSentinel}. */
export interface InfiniteScrollSentinelProps {
    /** Fired once each time the sentinel scrolls into view (and `disabled` is false). */
    onReach: () => void
    /** When true the observer is detached (e.g. no more pages / a load in flight). */
    disabled?: boolean
    /** Scroll root to observe within (defaults to the viewport). */
    root?: Element | null
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/**
 * Invisible end-of-list marker for infinite scroll: an `IntersectionObserver`
 * fires {@link InfiniteScrollSentinelProps.onReach} when it becomes visible, so
 * the list grows on scroll instead of via a "load more" button.
 *
 * Only for a list inside its OWN scroll container (modal / panel / rail) with
 * nothing below it. A list in the page's main column (footer underneath) must
 * use a "load more" button instead — auto-loading steals the scroll and the
 * footer becomes unreachable. A finite list the user browses to pick from wants
 * a pager instead (compose `AsyncContent` with a pagination control).
 *
 * Pair with `useSWRInfinite` — `onReach={() => setSize((s) => s + 1)}`,
 * `disabled={!hasMore || isLoadingMore}` where
 * `isLoadingMore = isValidating && (pages?.length ?? 0) < size`. While a page is
 * in flight, render skeletons mirroring 1-2 real items right here at the
 * sentinel, never a bare "loading" line.
 *
 * @see Story: .storybook/stories/blocks/async/InfiniteScrollSentinel/InfiniteScrollSentinel.stories
 * @param props - {@link InfiniteScrollSentinelProps}
 */
export const InfiniteScrollSentinel = ({
    onReach,
    disabled = false,
    root = null,
    classNames,
}: InfiniteScrollSentinelProps) => {
    const ref = React.useRef<HTMLDivElement>(null)
    // keep the latest callback without re-subscribing the observer each render
    const onReachRef = React.useRef(onReach)
    onReachRef.current = onReach

    React.useEffect(() => {
        const node = ref.current
        if (!node || disabled) {
            return
        }
        const observer = new IntersectionObserver(
            (entries) => {
                if (entries.some((entry) => entry.isIntersecting)) {
                    onReachRef.current()
                }
            },
            { root, rootMargin: "120px" },
        )
        observer.observe(node)
        return () => observer.disconnect()
    }, [disabled, root])

    return (
        <div
            ref={ref}
            aria-hidden
            data-tier="atom"
            data-component="InfiniteScrollSentinel"
            className={cn("h-px w-full", classNames)}
        />
    )
}

/** Tier metadata for `InfiniteScrollSentinel`, used by the component registry/Storybook lookup. */
export const meta = { tier: "atom", name: "InfiniteScrollSentinel" } as const

"use client"

import React, { useEffect, useRef } from "react"
import { publicEnv } from "@/resources/env/public"

/** Props for {@link Turnstile}. */
export interface TurnstileProps {
    /** Callback triggered when Turnstile successfully validates the visitor. */
    onVerify: (token: string) => void
    /** Callback triggered when Turnstile token expires. */
    onExpire?: () => void
    /** Callback triggered on network or verification error. */
    onError?: () => void
}

/** Render options passed to `turnstile.render()`. */
interface TurnstileRenderOptions {
    sitekey: string
    callback: (token: string) => void
    "expired-callback": () => void
    "error-callback": () => void
}

/** Minimal subset of the Cloudflare Turnstile global API used in this module. */
interface TurnstileApi {
    render: (container: HTMLElement, options: TurnstileRenderOptions) => string
    remove: (widgetId: string) => void
}

/** Window augmented with the optional Turnstile global. */
interface WindowWithTurnstile extends Window {
    turnstile?: TurnstileApi
}

/**
 * Renders the Cloudflare Turnstile captcha widget dynamically.
 * Automatically loads the Turnstile script if not already present.
 * No-ops (returns null) when captcha is disabled in public config.
 */
export const Turnstile = ({ onVerify, onExpire, onError}: TurnstileProps) => {
    const containerRef = useRef<HTMLDivElement>(null)
    const widgetIdRef = useRef<string | null>(null)

    useEffect(() => {
        const { enabled, siteKey } = publicEnv().captcha
        if (!enabled) return

        let isMounted = true

        const renderWidget = () => {
            const turnstile = (window as WindowWithTurnstile).turnstile
            if (!isMounted || !containerRef.current || !turnstile) return

            try {
                if (widgetIdRef.current !== null) {
                    turnstile.remove(widgetIdRef.current)
                }

                widgetIdRef.current = turnstile.render(containerRef.current, {
                    sitekey: siteKey,
                    callback: (token: string) => {
                        if (isMounted) onVerify(token)
                    },
                    "expired-callback": () => {
                        if (isMounted && onExpire) onExpire()
                    },
                    "error-callback": () => {
                        if (isMounted && onError) onError()
                    },
                })
            } catch (err) {
                console.error("[Turnstile] Render error:", err)
            }
        }

        const scriptId = "cloudflare-turnstile-script"
        let script = document.getElementById(scriptId) as HTMLScriptElement | null

        if (!script) {
            script = document.createElement("script")
            script.id = scriptId
            script.src = "https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit"
            script.async = true
            script.defer = true
            document.body.appendChild(script)
        }

        const turnstile = (window as WindowWithTurnstile).turnstile
        if (turnstile) {
            renderWidget()
        } else {
            const onLoad = () => {
                renderWidget()
            }
            script.addEventListener("load", onLoad)
            return () => {
                isMounted = false
                script?.removeEventListener("load", onLoad)
                const activeTurnstile = (window as WindowWithTurnstile).turnstile
                if (widgetIdRef.current !== null && activeTurnstile) {
                    activeTurnstile.remove(widgetIdRef.current)
                }
            }
        }

        return () => {
            isMounted = false
            const activeTurnstile = (window as WindowWithTurnstile).turnstile
            if (widgetIdRef.current !== null && activeTurnstile) {
                activeTurnstile.remove(widgetIdRef.current)
            }
        }
    }, [onVerify, onExpire, onError])

    const { enabled } = publicEnv().captcha
    if (!enabled) return null

    return <div ref={containerRef} className={"flex justify-center my-2 min-h-[74px]"} />
}
export default Turnstile

import { CloseButton as HeroCloseButton, cn } from "@heroui/react"

/**
 * Tone that drives the close button's colour + hover tint. Maps 1:1 to the app's
 * semantic colours; `neutral` is the quiet grey default.
 */
export type ElementCloseButtonTone = "neutral" | "accent" | "success" | "warning" | "danger"

/**
 * Per-tone colour + hover fill (LITERAL classes — Tailwind can't see interpolated
 * ones). The `!` beats HeroUI's UNLAYERED `.close-button--default` base
 * (`bg-default text-muted`), which a plain utility would lose to. This is the SAME
 * "text-<tone> + hover:bg-<tone>/10" treatment `Callout` used ad-hoc, now shared so
 * every close button reads consistently: hover = a tint of its OWN tone.
 */
const TONE: Record<ElementCloseButtonTone, string> = {
    neutral: "!text-muted hover:!bg-default",
    accent: "!text-accent-soft-foreground hover:!bg-accent-soft",
    success: "!text-success-soft-foreground hover:!bg-success-soft",
    warning: "!text-warning-soft-foreground hover:!bg-warning-soft",
    danger: "!text-danger-soft-foreground hover:!bg-danger-soft",
}

/** Props for {@link ElementCloseButton}. */
export interface ElementCloseButtonProps {
    /** Accessible label (the caller passes an already-resolved string, e.g. `t("common.close")`). */
    label: string
    /** Fired when the close/dismiss button is pressed. */
    onPress: () => void
    /**
     * Colour + hover-tint tone. Defaults to `neutral`. Pass the OWNER's tone so the
     * X reads tonal (a warning callout → warning X, an accent chip → accent X).
     */
    tone?: ElementCloseButtonTone
}

/**
 * The design-system close/dismiss "×" — a thin wrapper over HeroUI `CloseButton`
 * that bakes the shared look so callers don't re-style it ad-hoc:
 *
 * - **TRANSPARENT at rest** (icon only, no grey pill) — a fill of its own tone only
 *   on hover, so it never sits as a permanent grey square.
 * - **Tonal colour** (`tone`) — the × and its hover tint follow the owner's semantic
 *   colour, matching the surface it dismisses.
 *
 * All styling is per-instance (`!` utilities on THIS element), so it never leaks to
 * close buttons elsewhere (no global `.close-button` override). Use for a Callout
 * dismiss, a removable chip's cancel-X, a dismissible banner, etc.
 *
 * No house atom wraps HeroUI's `CloseButton` yet, so the vendor import stays here
 * (single unwrapped primitive, no atom equivalent to reuse) rather than being
 * invented as a new shared atom.
 *
 * @param props - {@link ElementCloseButtonProps}
 * @see Story: .storybook/stories/blocks/buttons/ElementCloseButton/ElementCloseButton.stories
 */
export const ElementCloseButton = ({ label, onPress, tone = "neutral" }: ElementCloseButtonProps) => {
    return (
        <HeroCloseButton
            data-tier="atom"
            data-component="ElementCloseButton"
            aria-label={label}
            onPress={onPress}
            className={cn("shrink-0", "!bg-transparent", TONE[tone])}
        />
    )
}

"use client"

import React, { useState, type ComponentType } from "react"
import { ScrollShadow, cn } from "@heroui/react"
import { AnimatePresence, motion } from "framer-motion"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"

/** Props for the {@link FlipCard} block. */
export interface FlipCardProps {
    /** Whether the answer card is currently revealed below the question. */
    revealed: boolean
    /** Label shown OUTSIDE (above) the question card — e.g. "Question". */
    questionLabel: string
    /** Label shown OUTSIDE (above) the answer card — e.g. "Answer". */
    answerLabel: string
    /** Front (prompt) content — a buildable slot that sits in the question card. */
    front: ComponentType
    /**
     * Optional slot rendered DIRECTLY under the question card (grouped with it,
     * `gap-3`) — ABOVE the answer, so it stays anchored to the question when the
     * answer reveals below (teacher 2026-07-13: "chips gap-3 under the question"). Used for
     * the card's level/tag chips.
     */
    belowFront?: ComponentType
    /** Back (answer) content — a buildable slot shown once {@link revealed}. */
    back: ComponentType
}

/**
 * Anki-style "no-flip" prompt/answer pair: the question and the answer are TWO
 * SEPARATE {@link LabeledCard}s — each label ("Question" / "Answer") sits OUTSIDE,
 * above its card (teacher 2026-07-12: "question, answer outside as a labeled card"),
 * not an eyebrow inside the card. The answer card reveals below the question one
 * (height-animate) once {@link revealed}. Retrieval-practice research (teacher
 * 2026-07-11) says what matters for recall is committing to an answer BEFORE
 * seeing it — the caller owns the "Show answer" reveal control and renders it
 * BETWEEN this block and the rating; this block is purely presentational.
 * @param props - {@link FlipCardProps}
 */
export const FlipCard = ({ revealed, questionLabel, answerLabel, front: Front, belowFront: BelowFront, back: Back}: FlipCardProps) => {
    // `overflow-hidden` is only needed WHILE the height animates — left on at
    // rest, it permanently clips the answer `Card`'s own box-shadow along every
    // edge, so it read flatter than the question card right above it (teacher:
    // "can the yellow one render as a card like the red one, with a
    // shadow..."). Drop it once the reveal animation settles so the shadow
    // shows in full, same as the un-clipped question card.
    const [animating, setAnimating] = useState(false)
    return (
        <div className={"flex flex-col gap-6"}>
            {/* question card + its `belowFront` chips grouped `gap-3` — the chips
                stay under the QUESTION when the answer reveals below (not pushed
                to the bottom of the answer). */}
            <div className="flex flex-col gap-3">
                <LabeledCard label={questionLabel} bordered>
                    <Front />
                </LabeledCard>
                {BelowFront ? <BelowFront /> : null}
            </div>
            {/* answer = its OWN labeled card, revealed below (height-animate so the
                reveal still feels connected) */}
            <AnimatePresence initial={false}>
                {revealed ? (
                    <motion.div
                        key="answer"
                        initial={{ height: 0, opacity: 0 }}
                        animate={{ height: "auto", opacity: 1 }}
                        exit={{ height: 0, opacity: 0 }}
                        transition={{ duration: 0.25, ease: "easeInOut" }}
                        onAnimationStart={() => setAnimating(true)}
                        onAnimationComplete={() => setAnimating(false)}
                        className={cn(animating && "overflow-hidden")}
                    >
                        <LabeledCard label={answerLabel} bordered>
                            <ScrollShadow hideScrollBar className="flex max-h-[28rem] flex-col gap-3 overflow-y-auto text-left">
                                <Back />
                            </ScrollShadow>
                        </LabeledCard>
                    </motion.div>
                ) : null}
            </AnimatePresence>
        </div>
    )
}

"use client"

import React from "react"
/** Props for {@link HighlightCard}. */
export interface HighlightCardProps {
    /** The wrapped card (e.g. a `SectionCard`/`Card`) — `HighlightCard` only adds the sweeping-light layer, it renders no card chrome of its own. */
    children: React.ReactNode
}

/**
 * Wraps a card with a single accent-colored arc SWEEPING around it, sitting as its own
 * layer BEHIND it (peeking out past the edges by 2px) — a pure "stand-out"
 * decoration, NOT a data signal (contrast with `SectionCard`'s `withVerdict`, a static
 * left band that DOES encode band/tier/zone data — `card.md` §3i vs §3j). Renders as 2
 * stacked cards: the INNER layer (bigger, behind, carries the sweeping-light effect) and
 * the wrapped card itself (OUTER, in front, 2px smaller in radius) — see `card.md` §3j
 * for why this is 2 layers and not a `SectionCard` prop. Use for the ONE card that
 * genuinely needs to stand out on a surface (e.g. a "resume your session" hero) —
 * multiple highlighted cards on the same screen cancel each other's emphasis out.
 *
 * @param props - {@link HighlightCardProps}
 * @see Story: .storybook/stories/blocks/cards/HighlightCard/HighlightCard.stories
 */
export const HighlightCard = ({ children}: HighlightCardProps) => (
    <div className={"relative"}>
        <div aria-hidden className="highlight-card-sweep" />
        {children}
    </div>
)

"use client"

import React from "react"
import type { ReactNode } from "react"
import { Tabs, cn } from "@heroui/react"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { ExtendedTabs } from "@/components/blocks/navigation/ExtendedTabs"

/** One tab of a {@link CodeConsole} (e.g. "Test case", "Result"). */
export interface CodeConsoleTab {
    /** Stable tab id. */
    key: string
    /** Tab label. */
    label: ReactNode
    /** Panel content shown when this tab is selected. */
    content: ReactNode
}

/** Props for the {@link CodeConsole} block. */
export interface CodeConsoleProps extends WithClassNames<undefined> {
    /** Accessible label for the tab list. */
    ariaLabel: string
    /** The console tabs, in order. */
    tabs: Array<CodeConsoleTab>
    /** Selected tab id (controlled). */
    selectedTab: string
    /** Fired with the newly selected tab id. */
    onSelectTab: (key: string) => void
    /** Right-aligned action controls in the footer bar (e.g. Run / Submit). */
    actions: ReactNode
    /** Optional muted hint shown at the left of the footer bar. */
    hint?: ReactNode
}

/**
 * The bottom CONSOLE of a code workspace: a tab strip ({@link ExtendedTabs}) over
 * a scrollable panel, capped by a footer action bar (Run / Submit). Sits under an
 * editor, delineated by a top border; the block owns the shell (tabs · scroll ·
 * footer seam) so a feature only feeds tab content + the action controls. The
 * LeetCode-style console pattern — testcases and results in tabs, actions pinned.
 *
 * @param props - {@link CodeConsoleProps}
 * @see Story: .storybook/stories/blocks/code/CodeConsole/CodeConsole.stories
 */
export const CodeConsole = ({
    ariaLabel,
    tabs,
    selectedTab,
    onSelectTab,
    actions,
    hint,
    className,
}: CodeConsoleProps) => {
    const active = tabs.find((tab) => tab.key === selectedTab) ?? tabs[0]

    return (
        <div className={cn("flex min-h-0 flex-col border-t border-default bg-surface", className)}>
            <div className="px-3 pt-1">
                <ExtendedTabs selectedKey={selectedTab} onSelectionChange={onSelectTab}>
                    <Tabs.ListContainer>
                        <Tabs.List aria-label={ariaLabel}>
                            {tabs.map((tab) => (
                                <Tabs.Tab key={tab.key} id={tab.key}>
                                    {tab.label}
                                    <Tabs.Indicator />
                                </Tabs.Tab>
                            ))}
                        </Tabs.List>
                    </Tabs.ListContainer>
                </ExtendedTabs>
            </div>

            <div className="min-h-0 flex-1 overflow-auto p-3">
                {active?.content}
            </div>

            <div className="flex items-center justify-between gap-3 border-t border-default px-3 py-2">
                {hint ? <span className="text-xs text-muted">{hint}</span> : <span />}
                <div className="flex items-center gap-2">{actions}</div>
            </div>
        </div>
    )
}

import React from "react"
import type { ReactNode } from "react"
import { cn } from "@heroui/react"

/** Semantic tone of one IO row's label (drives the label colour only). */
export type IORowTone = "default" | "success" | "danger"

/** One labelled monospace block inside an {@link IOExampleCard}. */
export interface IOExampleRow {
    /** Stable key. */
    key: string
    /** Small muted label above the value (e.g. "Input", "Expected"). */
    label: ReactNode
    /** The literal value, rendered monospace and pre-wrapped. */
    value: string
    /** Label tone — `success`/`danger` tint the label for a expected-vs-got diff. */
    tone?: IORowTone
}

/** Props for the {@link IOExampleCard} block. */
export interface IOExampleCardProps {
    /** The labelled blocks, in order — separated by a dashed inset rule. */
    rows: Array<IOExampleRow>
}

/** Label colour per tone. */
const TONE_CLASS: Record<IORowTone, string> = {
    default: "text-muted",
    success: "text-success",
    danger: "text-danger",
}

/**
 * A bounded card that renders one or more LABELLED monospace blocks — a sample
 * testcase (input → output), or a failed-case diff (input · expected · got with
 * tinted labels). Replaces the hand-rolled `<pre className="bg-default-100">`
 * scattered across the coding surfaces so every IO block reads the same: a small
 * muted label over a mono, pre-wrapped value, rows split by a dashed inset rule.
 * Presentational + props-only.
 *
 * @param props - {@link IOExampleCardProps}
 * @see Story: .storybook/stories/blocks/code/IOExampleCard/IOExampleCard.stories
 */
export const IOExampleCard = ({ rows}: IOExampleCardProps) => {
    return (
        <div className={"overflow-hidden rounded-3xl border border-default bg-surface"}>
            {rows.map((row, index) => (
                <div
                    key={row.key}
                    className={cn("px-3 py-2", index > 0 && "border-t border-dashed border-default")}
                >
                    <div className={cn("text-xs font-medium", TONE_CLASS[row.tone ?? "default"])}>
                        {row.label}
                    </div>
                    <pre className="mt-1 whitespace-pre-wrap break-words font-mono text-sm text-foreground">
                        {row.value}
                    </pre>
                </div>
            ))}
        </div>
    )
}

"use client"

import React from "react"
import {
    SandpackProvider,
    SandpackLayout,
    SandpackCodeEditor,
    SandpackPreview,
    SandpackFileExplorer,
} from "@codesandbox/sandpack-react"
import type { SandpackFiles, SandpackTheme } from "@codesandbox/sandpack-react"

const sharedFont = {
    body: "-apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif",
    mono: "'Fira Code', 'Cascadia Code', 'JetBrains Mono', monospace",
    size: "13px",
    lineHeight: "1.6",
}

/** Editor dark theme — surface1 matches the platform page background to blend in. */
const darkTheme: SandpackTheme = {
    colors: {
        surface1: "oklch(12.00% 0.0033 185.90)",
        surface2: "oklch(16.00% 0.0033 185.90)",
        surface3: "oklch(22.00% 0.0033 185.90)",
        clickable: "#6b7280",
        base: "#d1d5db",
        disabled: "#4b5563",
        hover: "#e5e7eb",
        accent: "#2dd4bf",
        error: "#f87171",
        errorSurface: "#1f1212",
    },
    syntax: {
        plain: "#e5e7eb",
        comment: { color: "#6b7280", fontStyle: "italic" },
        keyword: "#c084fc",
        tag: "#f472b6",
        punctuation: "#9ca3af",
        definition: "#60a5fa",
        property: "#34d399",
        static: "#fbbf24",
        string: "#86efac",
    },
    font: sharedFont,
}

/** Editor light theme — surface1 matches the platform page background to blend in. */
const lightTheme: SandpackTheme = {
    colors: {
        surface1: "oklch(97.02% 0.0033 185.90)",
        surface2: "oklch(94.00% 0.0033 185.90)",
        surface3: "oklch(90.00% 0.0033 185.90)",
        clickable: "#71717a",
        base: "#27272a",
        disabled: "#a1a1aa",
        hover: "#18181b",
        accent: "#0d9488",
        error: "#dc2626",
        errorSurface: "#fef2f2",
    },
    syntax: {
        plain: "#27272a",
        comment: { color: "#a1a1aa", fontStyle: "italic" },
        keyword: "#9333ea",
        tag: "#db2777",
        punctuation: "#52525b",
        definition: "#2563eb",
        property: "#059669",
        static: "#b45309",
        string: "#15803d",
    },
    font: sharedFont,
}

/** Props for {@link SandpackPanel}. */
export interface SandpackPanelProps {
    /** Assembled files map (stubs + github files + dynamic overrides). */
    files: SandpackFiles
    /** Extra npm dependencies merged from the lesson's package.json. */
    dependencies?: Record<string, string>
    /** When true, use the dark editor theme (follows the platform theme). */
    isDark?: boolean
}

/**
 * External resources injected into the preview iframe by Sandpack itself
 * (the bundler ignores <script>/<link> tags inside index.html). Loads Tailwind
 * v4 utilities (runtime DOM scan) + HeroUI v3 compiled styles via CDN.
 */
const EXTERNAL_RESOURCES = [
    "https://cdn.jsdelivr.net/npm/@tailwindcss/browser@4",
    "https://cdn.jsdelivr.net/npm/@heroui/styles@3/dist/heroui.min.css",
]

/** Live in-browser React sandbox (Sandpack) previewing the lesson's code files. */
export const SandpackPanel = ({ files, dependencies = {}, isDark = true}: SandpackPanelProps) => (
    <div>
        <SandpackProvider
            template="react-ts"
            theme={isDark ? darkTheme : lightTheme}
            files={files}
            customSetup={{ dependencies }}
            options={{
                recompileMode: "delayed",
                recompileDelay: 600,
                externalResources: EXTERNAL_RESOURCES,
                // load the embedded preview at /?sandbox=1 so lesson frontends that
                // split into Local/Sandbox render the multi-client Sandbox content;
                // frontends without the split simply ignore the query param.
                startRoute: "/?sandbox=1",
            }}
        >
            <SandpackLayout style={{ border: "none", borderRadius: 0, minHeight: 520, width: "100%" }}>
                {/* left half — source: file tree + code editor */}
                <SandpackFileExplorer style={{ width: 190, height: 520 }} />
                <SandpackCodeEditor showLineNumbers showTabs={false} showReadOnly={false} style={{ flex: 1, height: 520 }} />
                {/* right half — live UI preview */}
                <SandpackPreview showNavigator={false} showOpenInCodeSandbox style={{ flex: 1, height: 520 }} />
            </SandpackLayout>
        </SandpackProvider>
    </div>
)

"use client"

import React, { useEffect, useState } from "react"
import type { ReactNode } from "react"
import { cn } from "@heroui/react"
import { CheckIcon, XIcon } from "@phosphor-icons/react"
import { IOExampleCard } from "@/components/blocks/code/IOExampleCard"

/** One testcase outcome shown as a selectable pill + (sample) IO detail. */
export interface TestCaseResult {
    /** Stable key. */
    key: string
    /** Pill label (e.g. "Case 1"). */
    label: ReactNode
    /** Whether this case passed. */
    passed: boolean
    /** Sample cases carry IO; hidden cases show only the verdict pill. */
    isSample: boolean
    /** Sample-only: the stdin fed to the program. */
    input?: string | null
    /** Sample-only: the expected stdout. */
    expectedOutput?: string | null
    /** Sample-only: the program's actual stdout. */
    got?: string | null
}

/** Localised labels for the selected-case IO rows (caller passes translations). */
export interface TestCaseResultLabels {
    /** Label above the input value. */
    input: ReactNode
    /** Label above the expected value. */
    expected: ReactNode
    /** Label above the actual (got) value. */
    got: ReactNode
    /** Note shown when the selected case is a hidden (non-sample) case. */
    hidden: ReactNode
}

/** Props for the {@link TestCaseResultGrid} block. */
export interface TestCaseResultGridProps {
    /** The per-case outcomes, in evaluation order. */
    cases: Array<TestCaseResult>
    /** Localised labels for the selected sample case's IO rows. */
    labels: TestCaseResultLabels
}

/** Index of the first failing case, or 0 when all passed / empty. */
const firstFailingIndex = (cases: Array<TestCaseResult>): number => {
    const index = cases.findIndex((testcase) => !testcase.passed)
    return index >= 0 ? index : 0
}

/**
 * Renders a judged submission's PER-CASE outcome: a wrap of selectable pills
 * (Case N with a ✓/✕ glyph, tinted pass/fail) over the selected case's detail.
 * A sample case expands to an {@link IOExampleCard} (input · expected · got, with
 * the mismatch tinted on a failure); a hidden case shows only a muted note (its
 * IO never leaves the server). Selection defaults to the FIRST FAILING case so a
 * learner lands straight on what broke. Feeds off the decoded `perCaseResults`
 * the API already returns — data the old UI discarded.
 *
 * @param props - {@link TestCaseResultGridProps}
 * @see Story: .storybook/stories/blocks/code/TestCaseResultGrid/TestCaseResultGrid.stories
 */
export const TestCaseResultGrid = ({ cases, labels}: TestCaseResultGridProps) => {
    const [selected, setSelected] = useState<number>(() => firstFailingIndex(cases))

    // re-home the selection on the first failing case whenever the result set changes
    // (a new submission arrives) so the pane never points at a stale index.
    useEffect(() => {
        setSelected(firstFailingIndex(cases))
    }, [cases])

    if (cases.length === 0) {
        return null
    }

    const active = cases[Math.min(selected, cases.length - 1)]

    return (
        <div className={"flex flex-col gap-3"}>
            <div className="flex flex-wrap gap-2">
                {cases.map((testcase, index) => {
                    const isActive = index === Math.min(selected, cases.length - 1)
                    return (
                        <button
                            key={testcase.key}
                            type="button"
                            onClick={() => setSelected(index)}
                            className={cn(
                                "flex items-center gap-2 rounded-lg px-3 py-1 text-xs font-medium outline-none transition-colors",
                                "focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-accent",
                                testcase.passed
                                    ? "bg-success-soft text-success-soft-foreground"
                                    : "bg-danger-soft text-danger-soft-foreground",
                                isActive && "ring-2 ring-inset ring-accent",
                            )}
                        >
                            {testcase.passed ? (
                                <CheckIcon className="size-4" aria-hidden focusable="false" />
                            ) : (
                                <XIcon className="size-4" aria-hidden focusable="false" />
                            )}
                            {testcase.label}
                        </button>
                    )
                })}
            </div>

            {active.isSample ? (
                <IOExampleCard
                    rows={[
                        ...(active.input != null
                            ? [{ key: "in", label: labels.input, value: active.input }]
                            : []),
                        ...(active.expectedOutput != null
                            ? [{
                                key: "exp",
                                label: labels.expected,
                                value: active.expectedOutput,
                                tone: active.passed ? undefined : ("success" as const),
                            }]
                            : []),
                        ...(!active.passed && active.got != null
                            ? [{ key: "got", label: labels.got, value: active.got, tone: "danger" as const }]
                            : []),
                    ]}
                />
            ) : (
                <p className="text-xs text-muted">{labels.hidden}</p>
            )}
        </div>
    )
}

"use client"

import React from "react"
import { FreeTierCard } from "@/components/blocks/commerce/FreeTierCard"
import { TierCard } from "@/components/blocks/commerce/TierCard"
import { useQueryAiSubscriptionTiersSwr } from "@/hooks/swr/api/graphql/queries/useQueryAiSubscriptionTiersSwr"
import { useQueryMyAiSettingsSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyAiSettingsSwr"

/** How many paid cards the resting grid holds — the free card plus these fills both columns. */
const SKELETON_PAID_CARDS = 3

/** Props for {@link TierGrid}. */
export interface TierGridProps {
    /**
     * First load, nothing in hand → the SAME cards render resting, in the SAME grid.
     * A separate `AiSubscriptionSkeleton` used to mirror this layout by hand, along
     * with one twin per card; all three are gone.
     */
    isSkeleton?: boolean
}

/**
 * Responsive grid of subscription tiers: the static free tier followed by the
 * purchasable paid tiers.
 *
 * Reads eligible tiers from the AI subscription SWR singleton and the user's
 * current tier from the AI settings singleton. Each {@link TierCard} is a list
 * item that self-opens the payment overlay for the buy action.
 *
 * @param props - {@link TierGridProps}
 */
export const TierGrid = ({
    isSkeleton = false}: TierGridProps) => {
    const { data: tiersData } = useQueryAiSubscriptionTiersSwr()
    const { data: mySettings } = useQueryMyAiSettingsSwr()

    /** Purchasable paid tiers from the query (empty until loaded). */
    const tiers = tiersData ?? []
    /** The user's current tier slug, or null for the free tier. */
    const currentTier = mySettings?.tier ?? null

    return (
        <div className={"grid grid-cols-1 gap-6 @app-sm:grid-cols-2"}>
            <FreeTierCard isCurrent={currentTier === null} isSkeleton={isSkeleton} />
            {isSkeleton
                ? Array.from({ length: SKELETON_PAID_CARDS }, (_card, index) => (
                    <TierCard
                        key={`pending-${index}`}
                        isSkeleton
                        isCurrent={false}
                    />
                ))
                : tiers.map((tier) => (
                    <TierCard
                        key={tier.tier}
                        tier={tier}
                        isCurrent={currentTier === tier.tier}
                    />
                ))}
        </div>
    )
}

import React from "react"
import {
    SearchAutocomplete,
    type SearchAutocompleteItem,
} from "@/components/atoms/forms/SearchAutocomplete"

/**
 * `ConsultantDirectoryCompanySearch` — a typed, debounced deep-link to one
 * recruiting company's page, sitting above the consultant grid on the directory
 * screen. It is not a grid filter: there is no server-side search over
 * consultants, only a company suggester, so it jumps straight to a known
 * company page. `isLoadingSuggestions` swaps the popover's content.
 */

/** One company the ES suggester matched against the typed query. */
export interface ConsultantCompanySuggestion {
    /** Stable company id — the payload handed back through `onSelectCompany`. */
    id: string
    /** Company display name, already localized/formatted by the caller. */
    label: string
}

/** Props for {@link ConsultantDirectoryCompanySearch}. */
export interface ConsultantDirectoryCompanySearchProps {
    /** Current text in the search field (controlled). */
    query: string
    /** Fired with the new query on every keystroke; the screen owns debouncing. */
    onQueryChange: (value: string) => void
    /** Company matches for the current query, already fetched by the screen. */
    suggestions: Array<ConsultantCompanySuggestion>
    /** `true` while the screen is waiting on the ES company-suggester. */
    isLoadingSuggestions?: boolean
    /** Fired with the picked company's id; the screen owns the route push. */
    onSelectCompany: (companyId: string) => void
}

/**
 * The company deep-link search row atop the consultant directory. See the file
 * header for why this is a jump-to-company control and not a grid filter.
 *
 * @param props - {@link ConsultantDirectoryCompanySearchProps}
 */
const ConsultantDirectoryCompanySearch = ({
    query,
    onQueryChange,
    suggestions,
    isLoadingSuggestions = false,
    onSelectCompany,
}: ConsultantDirectoryCompanySearchProps) => {
    const items: Array<SearchAutocompleteItem> = suggestions.map((company) => ({
        id: company.id,
        label: company.label,
    }))

    return (
        <div>
            <div>
                <SearchAutocomplete
                    items={items}
                    inputValue={query}
                    onInputChange={onQueryChange}
                    onSelect={onSelectCompany}
                    isLoading={isLoadingSuggestions}
                    // Owned wording: this field jumps to ONE company, it does not filter
                    // the grid below it — the placeholder has to say so or a visitor will
                    // type a role/skill and get nothing back.
                    placeholder="Search for a hiring company by name…"
                    emptyLabel="No companies found"

                />
            </div>
        </div>
    )
}

export { ConsultantDirectoryCompanySearch }

import React from "react"
import { Breadcrumbs } from "@/components/atoms/navigation/Breadcrumbs"
