"use client"

import React, {
    useEffect,
    useState,
} from "react"

/** Brand + celebratory palette for the falling pieces. */
const COLORS = ["#d6006e", "#eab308", "#16a34a", "#3b82f6", "#f97316", "#a855f7"]

/** Props for {@link Confetti}. */
export interface ConfettiProps {
    /**
     * Bump this to fire a burst (e.g. a counter incremented on a win). `0` stays
     * idle; each distinct non-zero value fires exactly one burst.
     */
    fireKey: number
    /** Piece count (default 90). */
    count?: number
}

/** One falling piece's randomised layout. */
interface Piece {
    id: string
    left: number
    delay: number
    duration: number
    color: string
    width: number
    rotate: number
}

/**
 * A lightweight, dependency-free confetti burst — a fixed, non-interactive overlay
 * that rains coloured pieces down the viewport once per `fireKey` change, then
 * clears itself. Pure CSS fall animation (no canvas, no library). Used to celebrate
 * a top-3 league finish when the viewer lands on a board where they've placed.
 *
 * @param props - {@link ConfettiProps}
 */
export const Confetti = ({
    fireKey,
    count = 90,
}: ConfettiProps) => {
    const [pieces, setPieces] = useState<Array<Piece>>([])

    useEffect(
        () => {
            if (!fireKey) {
                return
            }
            // randomise in the effect (client-only) so there is no SSR hydration drift
            const next: Array<Piece> = []
            for (let i = 0; i < count; i += 1) {
                next.push({
                    id: `${fireKey}-${i}`,
                    left: Math.random() * 100,
                    delay: Math.random() * 0.4,
                    duration: 2 + Math.random() * 1.5,
                    color: COLORS[i % COLORS.length],
                    width: 6 + Math.random() * 6,
                    rotate: Math.random() * 360,
                })
            }
            setPieces(next)
            const timer = window.setTimeout(() => setPieces([]), 4000)
            return () => window.clearTimeout(timer)
        },
        [fireKey, count],
    )

    if (pieces.length === 0) {
        return null
    }

    return (
        <div aria-hidden className="pointer-events-none fixed inset-0 z-50 overflow-hidden">
            <style>
                {"@keyframes starci-confetti-fall{0%{transform:translateY(-12vh) rotate(0deg);opacity:1}100%{transform:translateY(112vh) rotate(720deg);opacity:.85}}"}
            </style>
            {pieces.map((piece) => (
                <span
                    key={piece.id}
                    className="absolute top-0 rounded-[2px]"
                    style={{
                        left: `${piece.left}%`,
                        width: `${piece.width}px`,
                        height: `${piece.width * 0.6}px`,
                        backgroundColor: piece.color,
                        animation: `starci-confetti-fall ${piece.duration}s linear ${piece.delay}s forwards`,
                    }}
                />
            ))}
        </div>
    )
}

"use client"

import React from "react"
import { Link } from "@heroui/react"
import {
    useResolveRouteNavigation,
} from "./useResolveRouteNavigation"
/** Props for {@link EntityToken}. */
export interface EntityTokenProps {
    /**
     * Opaque global id of the entity — resolved to a route on click. Omit when
     * passing a direct {@link EntityTokenProps.href} instead.
     */
    globalId?: string | null
    /**
     * Direct (already-built, locale-prefixed) route to push on click — use when the
     * caller already knows the path (e.g. a course `displayId`), skipping the
     * resolve round-trip. Takes precedence over {@link EntityTokenProps.globalId}.
     */
    href?: string
    /** Token text (username / lesson title …). */
    label: string
    /**
     * Render as a full-width left-rail row (truncated, hover bg) instead of an
     * inline accent link. Defaults to inline.
     */
    block?: boolean
}

/**
 * A clickable entity reference inside the feed (GitHub-style `<user>`/`<challenge>`
 * token). On click it asks the route index (`resolveRoute(globalId)`) where the
 * entity lives, then navigates — the dashboard has no course context, so the
 * server resolves the path. Renders as plain bold text when not routable.
 * @param props - the entity global id + label
 */
export const EntityToken = ({
    globalId,
    href,
    label,
    block = false}: EntityTokenProps) => {
    // resolve-and-navigate lives in a shared hook (also used by whole-row list items)
    const { onPress, pending, routable } = useResolveRouteNavigation({ globalId, href })

    // block (left-rail row): full-width, truncated, link-style — hover underlines the
    // label (like a <Link>), no block fill; flush (no px) so it aligns with the card edge.
    if (block) {
        return (
            <button
                type="button"
                disabled={!routable || pending}
                onClick={onPress}
                className={"truncate py-1 text-left text-sm text-muted transition-colors hover:text-foreground hover:underline underline-offset-4 decoration-[var(--separator-tertiary)] disabled:opacity-60"}
            >
                {label}
            </button>
        )
    }

    // unresolvable target → non-interactive bold text
    if (!routable) {
        return (
            <span className="font-semibold text-foreground">{label}</span>
        )
    }

    return (
        <Link
            onPress={onPress}
            isDisabled={pending}
            className={"font-semibold text-foreground hover:underline underline-offset-4 decoration-[var(--separator-tertiary)] disabled:opacity-60 text-sm"}
        >
            {label}
        </Link>
    )
}

import React from "react"
import type { ReactNode } from "react"
import { UserAvatar } from "@/components/blocks/identity/UserAvatar"

/** Props for the {@link ActivityAvatar} block. */
export interface ActivityAvatarProps {
    /** Main avatar's username — drives the image / initials fallback. */
    username: string
    /** Uploaded avatar URL (a generated default is used when missing). */
    avatar?: string | null
    /** Activity-type icon (phosphor `*Icon`) shown in the soft-accent badge. */
    icon: ReactNode
}

/**
 * Facebook-style feed avatar: a {@link UserAvatar} with a small activity-type icon
 * badge at the bottom-right. The badge is an OPAQUE soft-accent disc (a `bg-surface`
 * base under a `bg-accent-soft` tint so the avatar never bleeds through) with an
